<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted} from 'vue';import {useMatches,useSlip} from '../stores/store';import {heroSlides,fmtTime} from '../data/mock';import {useI18n} from 'vue-i18n';import planesWebp from '../assets/hero-planes.webp';import planesPng from '../assets/hero-planes.png';const ms:any=useMatches(),slip=useSlip(),{locale}=useI18n();const tab=ref('highlights');const market=ref('1X2');const showFilters=ref(false);const liveOnly=ref(false);const todayOnly=ref(false);const liveIdx=Math.max(0,heroSlides.findIndex((x:any)=>x.enTitle==='Live Betting'));const slide=ref(liveIdx);const reducedMotion=ref(false);const isLiveSlide=computed(()=>heroSlides[slide.value]?.enTitle==='Live Betting');let t:any,s:any;onMounted(()=>{reducedMotion.value=window.matchMedia('(prefers-reduced-motion: reduce)').matches;t=setInterval(()=>ms.tick(),4000);const adv=()=>{slide.value=(slide.value+1)%heroSlides.length;s=setTimeout(adv,slide.value===liveIdx?10000:4500)};s=setTimeout(adv,10000)});onUnmounted(()=>{clearInterval(t);clearTimeout(s)});
function displayOdds(m:any){ if(market.value==='1X2') return m.odds; if(market.value==='OU') return [{sel:'Over 2.5',price:1.9},{sel:'Under 2.5',price:1.85}]; return [{sel:'BTTS Yes',price:1.8},{sel:'BTTS No',price:1.95}] }
const list=computed(()=>ms.list.filter((m:any)=>(ms.selectedSport==='All'||m.sport===ms.selectedSport)&&(tab.value==='highlights'?true:!m.live)&&(!liveOnly.value||m.live)&&(!todayOnly.value||new Date(m.kickoff).toDateString()===new Date().toDateString())));
const groups=computed(()=>{const g:Record<string,any[]>={};list.value.forEach((m:any)=>{const k=m.league+' • '+m.country;(g[k]=g[k]||[]).push(m)});return g});
const countries=computed<string[]>(()=>[...new Set<string>(ms.list.map((m:any)=>String(m.country)))]);
</script>
<template><section class="landing-hero"><div class="landing-text"><h1>{{locale==='sw'?'Bashiri. Shinda. Furahia.':'Bet. Win. Enjoy.'}}</h1><p>{{locale==='sw'?'Odds za moja kwa moja kwenye mechi kubwa — kwa TZS, kwa simu au kompyuta.':'Live odds on the biggest matches — in TZS, on mobile or desktop.'}}</p><router-link class="landing-cta" to="/live">{{locale==='sw'?'Bashiri Mubashara':'Bet Live'}}</router-link></div><picture class="landing-planes"><source type="image/webp" :srcset="planesWebp"/><img :src="planesPng" alt="" width="1280" height="873"/></picture></section>
<h2>{{$t('home')}} <span v-if="ms.selectedSport!=='All'">— {{ms.selectedSport}} <button @click="ms.setSport('All')">×</button></span></h2>
<div class="chips"><button :class="{active:tab==='highlights'}" @click="tab='highlights'">Highlights</button><button :class="{active:tab==='upcoming'}" @click="tab='upcoming'">Upcoming</button><button @click="showFilters=!showFilters">Filters</button><button :class="{active:todayOnly}" @click="todayOnly=!todayOnly">Today</button><label>Market <select v-model="market"><option>1X2</option><option value="OU">Over/Under 2.5</option><option value="BTTS">BTTS</option></select></label><span v-if="market!=='1X2'"><small>Showing {{market}} (derived mock columns; 1X2 remains default)</small></span></div>
<div v-if="showFilters" class="card"><label><input type="checkbox" v-model="liveOnly"/> Live only</label> <label>Sport: <select :value="ms.selectedSport" @change="ms.setSport(($event.target as any).value)"><option>All</option><option>Football</option><option>Basketball</option><option>Tennis</option><option>Cricket</option><option>Volleyball</option><option>eSoccer</option><option>Counter-Strike</option></select></label></div>
<div class="card"><b>Countries:</b> <span v-for="c in countries" :key="c"> {{c}} · </span> <RouterLink to="/livescore">Livescore →</RouterLink></div>
<div v-for="(items,league) in groups" :key="league"><h3>{{league}}</h3><div class="match" v-for="m in items" :key="m.id"><RouterLink :to="`/match/${m.id}`"><b>{{m.home}} vs {{m.away}}</b><br/><small>{{fmtTime(m.kickoff)}} EAT <span v-if="m.live" class="live">LIVE {{m.minute}}' {{m.hs}}-{{m.as}}</span></small></RouterLink><div class="odds"><button v-for="o in displayOdds(m)" :key="o.sel" @click="slip.toggle(m,o)">{{o.sel}}<b>{{o.price.toFixed(2)}}</b></button></div><RouterLink :to="`/match/${m.id}`">+{{m.marketsCount}} Markets</RouterLink></div></div>
<p v-if="!list.length">Hakuna mechi / No matches for this filter.</p><button @click="ms.loadMore()">Load More</button></template>
